-- Перераспределение улик дела 9704 v2 (дельта к прежнему 012, партии не сбрасываются)
begin;
alter table locations add column if not exists search_note text;
update locations set is_searchable = true, search_note = null, unlock_evidence_ids = array['43eaf70c-177d-516a-9ab2-7aecc9633e33','e34a96b0-5d0e-5414-9ef3-048071ef84ed']::uuid[] where id = '29196055-161c-5b4e-a38f-352cbf3e5032';
update locations set is_searchable = true, search_note = null, unlock_evidence_ids = array['54bf13bc-3525-5eec-9441-609d8ee21f59','7ada2011-2720-5b69-8a9c-9291fdad70e9']::uuid[] where id = '78a34a22-6cc3-50d3-b3a7-bf4a481856bc';
update locations set is_searchable = true, search_note = 'Осмотр ничего не дал. Слишком чисто для склада, где вчера разгружали фуру: полы метены, на столах ни бумажки. Тут прибрались до вас. Спрашивайте людей.', unlock_evidence_ids = array['54bf13bc-3525-5eec-9441-609d8ee21f59','7ada2011-2720-5b69-8a9c-9291fdad70e9']::uuid[] where id = '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed';
update locations set is_searchable = true, search_note = null, unlock_evidence_ids = array['f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba']::uuid[] where id = '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7';
update locations set is_searchable = true, search_note = null, unlock_evidence_ids = array['6a92b637-cb0c-5bf4-8495-f503839bf08c']::uuid[] where id = 'ee497c59-0b63-50e6-91fc-8c67893c99ed';
update locations set is_searchable = true, search_note = null, unlock_evidence_ids = array['cefb9e58-2cc4-5054-a43b-6216c7645217']::uuid[] where id = 'a2371d56-be63-59a7-81d4-f8745d432f5d';
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('b4e6a60f-b233-543e-b3b1-ae0a1427b6a1', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Следы обуви у въезда в гараж', 'Въезд в гараж, под свесом крыши. В слякоти следы обуви двух видов.
Первые: обувь женская, узкая, носок острый. Следы под подмёрзшей коркой.
Вторые: обувь мужская, крупного размера, протектор зимний, глубокий. Следы присыпаны тонким слоем снега.
Чьи раньше, чьи позже, видно на глаз: женские под коркой, мужские под снегом.', '29196055-161c-5b4e-a38f-352cbf3e5032', true, 'Следы у гаража', null, false, 'thing') on conflict (id) do update set case_id = excluded.case_id, name = excluded.name, description = excluded.description, location_id = excluded.location_id, is_relevant = excluded.is_relevant, generic_category = excluded.generic_category, requires_any = excluded.requires_any, auto_grant = excluded.auto_grant, kind = excluded.kind;
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('34e1077a-bcc2-53ac-90e8-702d023d03c7', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Борозды у гаража и фототаблица РОВД', 'Там же, у въезда, со стороны водительской двери, две параллельные борозды. Длина около метра. Неглубокие, края рваные. Будто что-то тяжёлое волокли, а оно упиралось.

Фототаблица РОВД, снимки № 3 и № 4.
Сартаков за рулём. Голова откинута на подголовник. Руки лежат на коленях, ладонями вверх. Левая нога подвёрнута под сиденье. На педали её нет.
Ворот куртки поднят и застёгнут до подбородка.', '29196055-161c-5b4e-a38f-352cbf3e5032', true, 'Борозды у гаража', null, false, 'thing') on conflict (id) do update set case_id = excluded.case_id, name = excluded.name, description = excluded.description, location_id = excluded.location_id, is_relevant = excluded.is_relevant, generic_category = excluded.generic_category, requires_any = excluded.requires_any, auto_grant = excluded.auto_grant, kind = excluded.kind;
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('a9b47e33-f5b4-57b9-9e16-1e41c38e7834', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Копоть на стене гаража', 'Задняя стена гаража, побелка. На высоте выхлопной трубы чёрное пятно копоти, веером вверх. Края жирные, сажа пачкает палец.
Двигатель здесь работал долго. Ворота были закрыты: на внутренней стороне створок тот же налёт.
В протоколе РОВД это пятно — главный довод: «грелся в машине, угорел».', '29196055-161c-5b4e-a38f-352cbf3e5032', true, 'Копоть на стене', null, false, 'thing') on conflict (id) do update set case_id = excluded.case_id, name = excluded.name, description = excluded.description, location_id = excluded.location_id, is_relevant = excluded.is_relevant, generic_category = excluded.generic_category, requires_any = excluded.requires_any, auto_grant = excluded.auto_grant, kind = excluded.kind;
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('5cdb3307-fe10-53c5-a365-6998256b7d7a', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Конверт «на похороны» с пятью стодолларовыми купюрами', 'Белый почтовый конверт без марки. Стоял в серванте, у рюмок. Карандашом, рукой Валентины Петровны: «От Фархада — на похороны».
Внутри пять купюр по сто долларов США. Новые, «с маленькой головой».
Отдала сама, не дожидаясь вопроса, зачем он нужен.', null, true, null, null, false, 'thing') on conflict (id) do update set case_id = excluded.case_id, name = excluded.name, description = excluded.description, location_id = excluded.location_id, is_relevant = excluded.is_relevant, generic_category = excluded.generic_category, requires_any = excluded.requires_any, auto_grant = excluded.auto_grant, kind = excluded.kind;
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('4cc34317-760f-577c-b05f-e0374aee4f23', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Журнал КПП базы: «Мамаджанов Ф., 16:10–16:40»', 'ЖУРНАЛ учёта посетителей и автотранспорта. КПП № 1.

(Страница за конец октября, выписка.)
28.10.96 | 09:15 | «КамАЗ» 45-17 | выгрузка, склад 3 | (подпись)
28.10.96 | 11:40 | Есенова Г. | в бухгалтерию | (подпись)
28.10.96 | 14:05 | «ГАЗель» | экспедитор Ли | (подпись)
28.10.96 | 16:10–16:40 | Мамаджанов Ф. | к Сартакову И. | пешком | (подпись)
28.10.96 | 17:20 | ЗИЛ | вывоз тары | (подпись)

(Последняя заполненная страница, выписка.)
23.11.96 | 11:30 | ЗИЛ | вывоз тары | (подпись)
23.11.96 | 17:55–19:10 | Ахметов Д. | ВАЗ-2109, белая | (подпись)
23.11.96 | 20:00 | заступил на смену Нуртазин Е. | (подпись)

Строчки как строчки. Таких здесь сотни. Почерк дневного дежурного ровный. В графе «цель визита» у Мамаджанова просто: «к Сартакову И.».', null, true, null, null, false, 'thing') on conflict (id) do update set case_id = excluded.case_id, name = excluded.name, description = excluded.description, location_id = excluded.location_id, is_relevant = excluded.is_relevant, generic_category = excluded.generic_category, requires_any = excluded.requires_any, auto_grant = excluded.auto_grant, kind = excluded.kind;
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('be5c249c-d25f-5239-865f-5aef2088bc61', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Пейджер охранного агентства на поясе Ерлана', 'Пейджер на клипсе, на ремне Нуртазина. Корпус потёрт. На обороте наклейка охранного агентства и номер абонента пейджинговой компании.
Память сообщений пуста: всё стёрто.
Вы просите показать пейджер. Ерлан долго возится с клипсой. Роняет пейджер на пол. Говорит, не глядя:
— Да там ничего нету. Служебное всё.', null, true, null, null, false, 'thing') on conflict (id) do update set case_id = excluded.case_id, name = excluded.name, description = excluded.description, location_id = excluded.location_id, is_relevant = excluded.is_relevant, generic_category = excluded.generic_category, requires_any = excluded.requires_any, auto_grant = excluded.auto_grant, kind = excluded.kind;
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('c2c5ba62-e24e-523f-93bc-d8909b28e717', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Подвал Шмидтов: люк, матрас, верёвки, лампа, окурки', 'ПРОТОКОЛ осмотра (выписка)
Эксперт-криминалист Сеитова Г.

В полу кухни люк. Крышка деревянная, с железным кольцом. Ведёт в подвал глубиной около 2 м, спуск по приставной лестнице.
В подвале: матрас ватный, ветхий; обрезки бельевой верёвки, узлы затянуты; ведро эмалированное.
На кухне у люка лампа керосиновая «летучая мышь», стекло закопчено. С лампы и крышки люка изъяты следы пальцев рук.
В щелях пола у люка шесть окурков папирос. Гильзы смяты «гармошкой»: так обычно мнут «Беломор».', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', true, 'Подвал', null, false, 'thing') on conflict (id) do update set case_id = excluded.case_id, name = excluded.name, description = excluded.description, location_id = excluded.location_id, is_relevant = excluded.is_relevant, generic_category = excluded.generic_category, requires_any = excluded.requires_any, auto_grant = excluded.auto_grant, kind = excluded.kind;
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('87af9a91-8540-5177-bdd6-3e156802fc75', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Шарф на матрасе в подвале', 'На матрасе, в изголовье, свёрнутый шарф. Мужской, серый, кашемировый, импортного производства. Мягкий, дорогой. Для этого подвала вещь чужая.
Свёрнут валиком, как подушка. На ткани пятна от сырости.', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', true, 'Шарф', null, false, 'thing') on conflict (id) do update set case_id = excluded.case_id, name = excluded.name, description = excluded.description, location_id = excluded.location_id, is_relevant = excluded.is_relevant, generic_category = excluded.generic_category, requires_any = excluded.requires_any, auto_grant = excluded.auto_grant, kind = excluded.kind;
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('552b22f9-f4c6-5469-8d1c-56bde54906aa', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Телефон в прихожей Шмидтов', 'Прихожая пустого дома. На стене телефонный аппарат, серый, дисковый. Гудок есть: линию не отключили.
Под диском бумажка, рукой хозяина: «48-27-15».
Тот самый номер. Он в памяти АОНа у Валентины Петровны: суббота, 15:30.
На трубке пыли нет. На полке рядом пыль в палец толщиной.', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', true, 'Телефон', null, false, 'thing') on conflict (id) do update set case_id = excluded.case_id, name = excluded.name, description = excluded.description, location_id = excluded.location_id, is_relevant = excluded.is_relevant, generic_category = excluded.generic_category, requires_any = excluded.requires_any, auto_grant = excluded.auto_grant, kind = excluded.kind;
delete from case_decoy_categories where case_id = '029e23c3-01e0-5d19-a0e7-3e0c2446ebab';
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Связка ключей');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Газета «Караван»');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Квитанция за свет');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Обрывок бумаги');
