insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Пуговица');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Спичечный коробок');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Зажигалка');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Мужская перчатка');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Аудиокассета');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Автобусный билет');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Талон на бензин');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Визитка');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Фотография');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Квитанция ломбарда');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Губная помада');
insert into case_decoy_categories (case_id, label) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Гильза');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Пустая бутылка', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Бутылка из-под «Жигулёвского» под яблоней. Этикетка размокла, внутри прелые листья. Лежит тут с осени.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Детская варежка', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Красная вязаная варежка на штакетнике. Детская. Кто-то нашёл и надел на штакетину, чтобы хозяин заметил. С прошлой зимы висит.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Сломанный зонт', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Чёрный складной зонт у крыльца. Спицы вывернуты ветром. Бросили и забыли.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Детский велосипед', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Детский велосипед под клеёнкой. Цепь в ржавчине, шины спущены. С лета не трогали.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Мешок угля', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Мешок угольных брикетов на крыльце, початый. А котёл холодный, зола старая: в эти выходные дом не топили.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Калитка', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Узкая калитка рядом с воротами. Щеколда задвинута. На щеколде паутина, в ней сухие листья. Через калитку давно никто не ходил.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Портрет с лентой', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Портрет Игоря в рамке, чёрная лента наискосок. Снимок с документа, увеличенный в фотоателье. Пиджак, галстук, взгляд в объектив.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Рюмка с хлебом', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Рюмка водки, накрытая куском чёрного хлеба. Так положено: для покойного. Водка не тронута.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Фотография', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Фото за стеклом серванта: девочка в школьной форме, белый фартук, банты. На обороте рукой Валентины Петровны: «Даша, 1 сентября 1996».');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Зеркало', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Зеркало в прихожей завешено простынёй. Пока покойник не похоронен, так положено.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Телеграммы', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Пачка телеграмм на подоконнике. Караганда, Москва, сослуживцы Игоря. «Скорбим вместе с вами». Все за воскресенье и понедельник.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Телевизор', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Телевизор «Горизонт» на тумбе с кружевной салфеткой. Выключен. В доме траур.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Конверт', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Конверт в серванте, у рюмок. Подписан карандашом: «От Фархада — на похороны». Чужие деньги без спроса не берут: спросите хозяйку.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Тарелки', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Тарелки на столе из разных сервизов: соседи несли кто что мог. К поминкам готовятся заранее, хотя тело ещё не отдали.');
update characters set reaction_rules = reaction_rules || '[{"id": "R67", "on": "a9b47e33-f5b4-57b9-9e16-1e41c38e7834", "requires": [], "text": "Сеитова трёт сажу между пальцами, нюхает.\n— Свежая. Мотор работал часа три, не меньше, на холостых, при закрытых воротах. Бак, говорите, сухой? Сходится.\n(вытирает руку платком)\nТолько копоть не скажет, был ли за рулём живой человек. Это вопрос к Кану, не ко мне.", "grants": []}]'::jsonb, reactions = coalesce(reactions,'{}'::jsonb) || '{"a9b47e33-f5b4-57b9-9e16-1e41c38e7834": "Сеитова трёт сажу между пальцами, нюхает.\n— Свежая. Мотор работал часа три, не меньше, на холостых, при закрытых воротах. Бак, говорите, сухой? Сходится.\n(вытирает руку платком)\nТолько копоть не скажет, был ли за рулём живой человек. Это вопрос к Кану, не ко мне."}'::jsonb where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';  -- Гульнара Сеитова
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R23' then jsonb_set(r, '{on}', '"34e1077a-bcc2-53ac-90e8-702d023d03c7"') else r end) from jsonb_array_elements(reaction_rules) r), reactions = coalesce(reactions,'{}'::jsonb) || '{"34e1077a-bcc2-53ac-90e8-702d023d03c7": "Бейсенов долго смотрит фототаблицу и схему следов. Постукивает карандашом.\n— Скажу, как это выглядит с точки зрения криминологии. Заложника, за которого получен выкуп, обычно отпускают. Мёртвый заложник похитителю ни к чему, это лишний риск. После выкупа убивают, как правило, в одном случае: похититель боится, что его опознают. То есть жертва его знала.\nДальше. Инсценировку делал человек, который знал дачу, знал привычки покойного и рассчитывал, что семья промолчит. Это не случайные люди. Это круг: друзья семьи, партнёры, бывшие супруги, охрана.\nИмён я не называю. Это закономерность, не больше."}'::jsonb where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';  -- Аскар Бейсенов
update characters set reaction_rules = reaction_rules || '[{"id": "R68", "on": "a9b47e33-f5b4-57b9-9e16-1e41c38e7834", "requires": [], "text": "Виктор смотрит на пятно, отворачивается.\n— Прогревать он любил, да. Минут пять, десять. Но во дворе! Ворота настежь. Он гаража боялся, говорил: душегубка.\nЧтобы он сам ворота закрыл и сидел... Нет. Не он это.", "grants": []}]'::jsonb, reactions = coalesce(reactions,'{}'::jsonb) || '{"a9b47e33-f5b4-57b9-9e16-1e41c38e7834": "Виктор смотрит на пятно, отворачивается.\n— Прогревать он любил, да. Минут пять, десять. Но во дворе! Ворота настежь. Он гаража боялся, говорил: душегубка.\nЧтобы он сам ворота закрыл и сидел... Нет. Не он это."}'::jsonb where id = '54b23338-3cf2-5d0a-99c4-91c0de226522';  -- Виктор Гринько
update characters set fixed_questions = jsonb_set(fixed_questions, '{4,requires}', '["87af9a91-8540-5177-bdd6-3e156802fc75"]'::jsonb) || '[{"q": "Что это за конверт в серванте?", "a": "— Это? Фархад-ака вчера вечером принёс. На похороны.\n(достаёт конверт, протягивает)\nСмотрите, смотрите. Пятьсот долларов. Золотой человек. У самого ничего нет, а принёс.\nЯ ему говорю: не надо. А он: «Валя-апа, это не вам. Это Игорю».", "grants_evidence_id": "5cdb3307-fe10-53c5-a365-6998256b7d7a"}]'::jsonb, reaction_rules = reaction_rules || '[{"id": "R69", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": [], "text": "Валентина Петровна берёт шарф двумя руками. Долго молчит.\n— Его. Я из Москвы привезла. Итальянский.\n(прижимает к лицу)\nСыростью пахнет. Где он лежал? Нет... Не говорите. Не надо.", "grants": []}]'::jsonb, reactions = coalesce(reactions,'{}'::jsonb) || '{"87af9a91-8540-5177-bdd6-3e156802fc75": "Валентина Петровна берёт шарф двумя руками. Долго молчит.\n— Его. Я из Москвы привезла. Итальянский.\n(прижимает к лицу)\nСыростью пахнет. Где он лежал? Нет... Не говорите. Не надо."}'::jsonb where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';  -- Валентина Петровна Сартакова
update characters set fixed_questions = fixed_questions || '[{"q": "Кто приходил к Игорю на базу в последнее время?", "a": "— Все приходят. Поставщики, экспедиторы, кредиторы. Всех не упомнишь.\n(достаёт из сейфа толстую амбарную книгу)\nЖурнал КПП. На проходной пишут всех, кто входит. Берите, мне не жалко. Я, в отличие от некоторых, ничего не скрываю.", "grants_evidence_id": "4cc34317-760f-577c-b05f-e0374aee4f23"}]'::jsonb where id = 'a7955352-673d-5ff7-bfcc-506079544d1f';  -- Данияр Ахметов
update characters set fixed_questions = fixed_questions || '[{"q": "Покажите ваш пейджер.", "a": "— Пейджер? Зачем? Служебный.\n(отстёгивает с ремня, не сразу)\nНа. Там пусто, смотри сколько хочешь.", "grants_evidence_id": "be5c249c-d25f-5239-865f-5aef2088bc61"}]'::jsonb where id = '2d9e7245-2e05-5079-86f1-f9b2edb1f3e9';  -- Ерлан Нуртазин
update characters set reaction_rules = reaction_rules || '[{"id": "R70", "on": "552b22f9-f4c6-5469-8d1c-56bde54906aa", "requires": [], "text": "Тамара Фёдоровна смотрит на аппарат.\n— Телефон? Не отключали, нет. Фархад сказал: покупатели звонить будут, пусть работает. Он и платил, наверное.\n(пауза)\nА кому оттуда звонить? Там же никого нет. Не было.", "grants": []}]'::jsonb, reactions = coalesce(reactions,'{}'::jsonb) || '{"552b22f9-f4c6-5469-8d1c-56bde54906aa": "Тамара Фёдоровна смотрит на аппарат.\n— Телефон? Не отключали, нет. Фархад сказал: покупатели звонить будут, пусть работает. Он и платил, наверное.\n(пауза)\nА кому оттуда звонить? Там же никого нет. Не было."}'::jsonb where id = '631694f6-0ec1-523d-9f2a-599f875223c1';  -- Тамара Фёдоровна Шнайдер
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R42' then jsonb_set(r, '{on}', '"87af9a91-8540-5177-bdd6-3e156802fc75"') else r end) from jsonb_array_elements(reaction_rules) r), reactions = coalesce(reactions,'{}'::jsonb) || '{"87af9a91-8540-5177-bdd6-3e156802fc75": "Перед Олжасом серый шарф из подвала. Вы пересказываете, что видели Данияр на остановке и соседка у дома Шмидтов: высокий, молодой, спортивная куртка, ушанка. Печь топил.\nОлжас смотрит на шарф. Глаз не отводит.\n— Он мёрз там...\n(и сразу, быстро)\nЯ его взял. В четверг, у ворот. Темно было.\nМашину к Шмидтам перегнал. Водить умею, прав нет.\nВ подвале держал. Матери его из автоматов звонил. А в субботу — из того дома, там телефон.\nПакет на остановке я забрал.\nНо аке ни при чём! Я сам придумал, слышите? Сам.\nУтром его отпустили, машину отдали — там же стояла, под навесом. Он на дачу поехал. И угорел. Бог наказал. Не я.\nСосед по комнате перестаёт притворяться спящим. На запястьях Олжаса щёлкают наручники."}'::jsonb where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';  -- Олжас Бекенов
commit;
notify pgrst, 'reload schema';
select (select count(*) from evidence where case_id = '029e23c3-01e0-5d19-a0e7-3e0c2446ebab') as evidence, (select count(*) from evidence where case_id = '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and location_id is not null) as searchable_ev, (select count(*) from game_sessions where id = 'ebd8093a-9023-532f-9b07-87d885dcf31a') as session_kept;
